require "test_helper"

# Generated by maquina:oauth.
class ConnectedApplicationTest < ActiveSupport::TestCase
  test "groups a person's unrevoked tokens by client" do
    application = ConnectedApplication.for(users(:mcp_member)).sole

    assert_equal oauth_clients(:inspector), application.client
    assert_equal ["read", "write"], application.scopes
    # An expired access token still counts: its refresh token works.
    assert_includes application.tokens, access_tokens(:mcp_member_expired)
    assert_not_includes application.tokens, access_tokens(:mcp_member_revoked)
  end

  test "lists nothing for someone who connected nothing" do
    assert_empty ConnectedApplication.for(users(:mcp_other))
  end

  test "finds only among the person's own connections" do
    assert_raises(ActiveRecord::RecordNotFound) { ConnectedApplication.find(users(:mcp_other), oauth_clients(:inspector).id) }
    assert ConnectedApplication.find(users(:mcp_member), oauth_clients(:inspector).id)
  end

  test "reports when it was connected and last used" do
    access_tokens(:mcp_member_read).update!(last_used_at: 5.minutes.ago)
    application = ConnectedApplication.for(users(:mcp_member)).sole

    assert_in_delta 5.minutes.ago, application.last_used_at, 1.second
    assert_equal application.tokens.map(&:created_at).min, application.connected_at
  end

  test "revoking stops every token and drops unused codes" do
    code = oauth_authorization_codes(:mcp_member)
    ConnectedApplication.find(users(:mcp_member), oauth_clients(:inspector).id).revoke!

    assert_nil AccessToken.authenticate(MEMBER_READ_ACCESS_TOKEN)
    assert_nil AccessToken.find_by_refresh_token(EXPIRED_REFRESH_TOKEN)
    assert_not OauthAuthorizationCode.exists?(code.id)
    assert AccessToken.authenticate(ADMIN_READ_ACCESS_TOKEN), "another person's grant is untouched"
  end
end
